/* Saved physical investigations and opening; independent of rendering. */
(()=>{'use strict';
const clue=(id,label,x,y,text)=>({id,label,x,y,text});
const cases={
0:{title:'The book beneath the dust',image:'library',intro:'Orren’s desk has not been touched since the festival. Search the archive for three pieces of the same story.',clues:[clue('register','Festival register',27,65,'A dated festival register records eight missing names and a transfer to Briar House.'),clue('seal','Gatekeeper’s seal',67,45,'The gatekeeper’s seal matches the register. This is an authentic record.'),clue('book','Silverstitched book',50,75,'A book fastened with silver thread opens: “Eight were lost beneath eight lanterns.”')],prompt:'Build your first lead: identify the missing people, verify the record, then follow its destination.',order:['register','seal','book'],solution:'The register names the missing children; the seal verifies the entry; the book connects the eight names to the Silverstitch family.'},
1:{title:'Lanternlight in the cellar',image:'cellar',intro:'Dust covers the shelves beneath Briar House. A scratched cabinet and a tangle of old cloth catch the light.',clues:[clue('cloth','Green-lined gray cloth',24,54,'The cloth is gray outside and green within. A figure in the memory wore these colors.'),clue('button','Cracked memory button',59,70,'The button shows seven children in a wagon and an eighth carried away separately.'),clue('mark','Cabinet scrape',77,79,'A silver glint beneath the broken cabinet points to something the searchers missed.')],prompt:'Reconstruct the cellar discovery: identify the cloak, examine the memory, then follow the silver glint.',order:['cloth','button','mark'],solution:'The button preserves a fragment of the abduction. The eighth child took a different route.'},
2:{title:'Something beneath the cabinet',image:'dormitory',intro:'You crouch beside the cabinet. Find a way to support it, recover the hidden object, and examine what it remembers.',clues:[clue('wedge','Wooden support wedge',24,80,'The wooden wedge supports the cabinet so the space beneath it can be searched.'),clue('shoe','First silver shoe',61,82,'A tiny silver shoe reflects Dain’s separate carriage and a closed-eye ring.'),clue('oak','Oak-leaf engraving',69,47,'An oak leaf engraved beneath the sole glows toward Whispering Woods.')],prompt:'Arrange the search safely: support the cabinet, recover the shoe, then read its destination.',order:['wedge','shoe','oak'],solution:'The shoe is recovered without damaging the evidence. Its engraving points to the Hollow Oak.'},
4:{title:'The Keeper’s memory table',image:'treehouse',intro:'The Keeper places three witnesses on a wooden table. Each remembers part of a night. Their accounts must be read together.',clues:[clue('button','Button memory',28,66,'The button recalls a woman in a gray cloak with a green lining, beside Mistress Vale’s wagon.'),clue('shoe','Shoe memory',54,72,'The shoe remembers a closed-eye ring above Dain’s separate carriage.'),clue('witness','Keeper’s witness account',76,49,'The witness identifies the closed-eye ring as Lady Ysabet Vale’s signal. The carriage went to House Vale.')],prompt:'Trace the chain: the wagon, the separate carriage, then the witness who identifies the signal.',order:['button','shoe','witness'],solution:'The memories support one another. Lady Ysabet’s signal and Mistress Vale’s wagon connect House Vale to the disappearances.'},
5:{title:'The room House Vale kept locked',image:'manor',intro:'Footsteps sound beyond the records chamber. You have time to search carefully. Secure Dain’s identity before approaching his door.',clues:[clue('ledger','Signed transfer ledger',31,68,'The ledger names Dain beneath a false identity. The payment and Lady Ysabet’s signature survive.'),clue('shoe','Second silver shoe',68,75,'The second silver shoe fits a small impression in the lock. You hear someone behind the door.'),clue('last','Finren’s Silver Last',77,45,'A single Silver Last bears Finren’s workshop mark. Its fitting belongs to the hidden village.')],prompt:'Prepare the escape: preserve the ledger, unlock Dain’s door, then recover the village’s Last.',order:['ledger','shoe','last'],solution:'The records are safe. Dain recognizes his name and chooses to leave. The Silver Last can reopen the village road.'},
9:{title:'Lay the case before the court',image:'royal',intro:'The magistrate clears the council table. Place independent records together so the family’s account can stand in public.',clues:[clue('register','Dated festival register',24,68,'The register establishes the date and the eight missing children.'),clue('ledger','Signed Vale ledger',51,72,'The signed transfer ledger establishes Dain’s false identity and House Vale’s payment.'),clue('witness','Independent witness account',76,56,'The Keeper’s testimony connects the ring signal, wagon, and separate transfer.')],prompt:'Present the case: establish the disappearance, show the signed transfer, then corroborate it with testimony.',order:['register','ledger','witness'],solution:'Dates, signatures, and independent testimony support one account. A title cannot erase the evidence.'}
};
function ensure(s){if(!s.cityExperience||typeof s.cityExperience!=='object'||Array.isArray(s.cityExperience))s.cityExperience={};const e=s.cityExperience;if(!e.investigations||typeof e.investigations!=='object'||Array.isArray(e.investigations))e.investigations={};return e}
function progress(s,step){const e=ensure(s);if(!e.investigations[step])e.investigations[step]={found:[],solved:false};return e.investigations[step]}
function valid(s,step,w){const m=globalThis.EldoriaStoryModel?.missions[step];return !!cases[step]&&s.silverStory?.step===step&&m&&w?.district===m.district&&w?.room===m.room&&!w?.porch}
function find(s,step,id,w){if(!valid(s,step,w)||!cases[step].clues.some(c=>c.id===id))return{ok:false};const p=progress(s,step);if(!p.found.includes(id))p.found.push(id);return{ok:true,text:cases[step].clues.find(c=>c.id===id).text}}
function assemble(s,step,ids,w){if(!valid(s,step,w))return{ok:false,reason:'Return to the current story location.'};const c=cases[step],p=progress(s,step);if(globalThis.EldoriaPromiseModel?.active(s)){p.found=c.clues.map(v=>v.id);ids=[...c.order]}if(!c.clues.every(v=>p.found.includes(v.id)))return{ok:false,reason:'Examine all three objects before connecting the evidence.'};if(!Array.isArray(ids)||ids.length!==c.order.length||ids.some((v,i)=>v!==c.order[i]))return{ok:false,reason:'Read the evidence notes and follow the sequence in the task.'};p.solved=true;return{ok:true,text:c.solution}}
function canAdvance(s,step){return !cases[step]||progress(s,step).solved===true}
globalThis.EldoriaExperienceModel={cases,ensure,progress,find,assemble,canAdvance};
})();
